mat_kombi_lines.vertex:
#version 100
precision highp float ;
attribute vec2 a_TextureCoordinate;
attribute vec3 a_Position;
attribute vec4 a_Color;
attribute vec4 a_Color1;
uniform mat4 u_MVPMatrix;
uniform float u_ExtendXPlus;
uniform float u_ExtendZMinus;
uniform float u_RightEdge;
uniform float u_LeftEdge;
varying vec2 uv;
void main(void) {
	uv = a_TextureCoordinate;
	float growX_plus = a_Color.b;
	float growZ_minus = a_Color.g;
	float edgeL = a_Color1.r;
	float edgeR = a_Color1.b;
	vec3 p = a_Position;
	p.x += (u_ExtendXPlus - 1.) * growX_plus;
	p.z -= (u_ExtendZMinus -1.)* growZ_minus;
	p.x += (u_LeftEdge*edgeL)*(u_ExtendZMinus - 0.5);
	p.x -= (u_RightEdge*edgeR)*(u_ExtendZMinus - 1.);
	gl_Position = u_MVPMatrix * vec4(p, 1.);
}

mat_kombi_lines.fragment:
#version 100
precision mediump float;
uniform sampler2D tex0;
uniform float u_opacity;
uniform vec3 u_color;
varying vec2 uv;
void main(void) {
	vec4 sample = texture2D(tex0, uv);
	vec4 shd = vec4(u_color, sample.b);
	gl_FragColor = shd;
	gl_FragColor.a *= u_opacity;
}

mat_bg_progress.vertex:
#version 100
precision highp float;
attribute vec2 a_TextureCoordinate;
attribute vec3 a_Position;
attribute vec4 a_Color;
uniform mat4 u_MVPMatrix;
uniform float u_divisions;
const float u_progress = float(0.000000); // const-optimized by shader optimizer!
uniform float u_ExtendXPlus;
varying vec2 uv, uvB;
varying float v_divisions, v_progress;
	uniform highp mat4 u_MMatrix;
	uniform highp vec4 u_ScrollAreaFadeParameters;
	uniform highp mat4 u_ScrollAreaInverseWorldTransformation;
	uniform highp float u_ScrollAreaDirection;
	varying vec2 vFading;
	vec2 calcMask( vec2 posXZ ) {
		vec2 result = vec2(1.,1.);
		if (u_ScrollAreaDirection < 0.0) {
			result.x = (posXZ.y - u_ScrollAreaFadeParameters.x) * u_ScrollAreaFadeParameters.y;
			result.y = 1.0 - ((posXZ.y - u_ScrollAreaFadeParameters.z) * u_ScrollAreaFadeParameters.w);
			}
		else if (u_ScrollAreaDirection > 0.0) {
			result.x = (posXZ.x - u_ScrollAreaFadeParameters.x) * u_ScrollAreaFadeParameters.y;
			result.y = 1.0 - ((posXZ.x - u_ScrollAreaFadeParameters.z) * u_ScrollAreaFadeParameters.w);
			}
		return result;
		}
void main(void) {
	uv = a_TextureCoordinate;
	uvB = a_TextureCoordinate;
	uvB.x *= u_divisions;
	float growXPlus = a_Color.r;
	vec3 p = a_Position;
	p.x += (u_ExtendXPlus + 1.) * growXPlus;
	vec4 pos = vec4(p.xyz, 1.0);
	gl_Position = u_MVPMatrix * pos;
	v_divisions = u_divisions;
	float progresssmall = 1.;
	v_progress = (mix(0., progresssmall, 1.) - uv.x) * 400.;
	vec4 scrollAreaPos = u_ScrollAreaInverseWorldTransformation * u_MMatrix * pos;
	vFading = calcMask( scrollAreaPos.xz );
}

mat_bg_progress.fragment:
#version 100
precision mediump float;
uniform sampler2D tex0;
uniform float u_opacity;
uniform float u_ContainerActive;
uniform vec3 u_color;
varying vec2 uv, uvB;
varying float v_divisions, v_progress;
varying highp vec2 vFading;
float subdivs( float div, float num ) {
	float hardness = 400./num;
	float width = 0.002*num;
	float sep = clamp( (div - width) * hardness, 0., 1.);
	sep *= clamp( ((1.-div) - width) * hardness, 0., 1.);
	return sep;
}
void main(void) {
vec2 fading = clamp(vFading, vec2(0.0), vec2(1.0));
float fade = fading.x * fading.y;
	float div = subdivs(fract(uvB.x), v_divisions);
	vec4 sample = texture2D(tex0, uv);
	vec4 shd = vec4(u_color * u_ContainerActive, sample.b);
	shd.a *= clamp(v_progress, 0., 1.);
	gl_FragColor = shd;
	gl_FragColor.a *= (u_opacity - (1. - div));
	gl_FragColor.a *= u_ContainerActive;
gl_FragColor.a *= fade;
}

